/* Custom CSS for Google Gemini chat box */

/* Target the main chat input area */
c-wiz[data-is-text-input] {
  min-height: 40px !important; /* Adjust this value to your desired smaller height */
  max-height: 80px !important; /* Set a max-height to prevent it from getting too tall with longer messages */
  overflow-y: auto; /* Add scroll if content exceeds the max-height */
}

/* You might also want to adjust the padding inside the input area if needed */
c-wiz[data-is-text-input] > div {
  padding-top: 5px !important;
  padding-bottom: 5px !important;
}

